  const { businessId, timeZone, staffId, serviceId, dateISO } = opts;
  const [service] = await db
    .select()
    .from(s.services)
    .where(and(eq(s.services.id, serviceId), eq(s.services.businessId, businessId)));
  if (!service?.isActive) return [];

  const window = await dayWindowFor(businessId, staffId, dateISO);
  if (!window) return [];

  const dayStart = localTimeToUtc(dateISO, "00:00", timeZone);
  const dayEnd = dayStart + 36 * 3600_000; // generous bound; window trims precisely
  const busyRows = await db
    .select({ startAt: s.bookings.startAt, endAt: s.bookings.endAt })
    .from(s.bookings)
    .where(
      and(
        eq(s.bookings.staffId, staffId),
        eq(s.bookings.status, "confirmed"),
        gte(s.bookings.endAt, new Date(dayStart)),
        lt(s.bookings.startAt, new Date(dayEnd)),
      ),
    );
  const busy = busyRows.map((b) => ({ startMs: b.startAt.getTime(), endMs: b.endAt.getTime() }));
  const holds = await listHolds(staffId, dayStart, dayEnd);

  return slotsForDay({
    dateISO,
    timeZone,
    window,
    durationMin: service.durationMin,
    busy,
    holds,
    notBeforeMs: Date.now(),
  });
}

// ---------- Booking creation ----------

export type BookResult =
  | { ok: true; bookingId: string }
}) {
  const session = await requireSession();
  const [biz] = await db.select().from(s.businesses).where(eq(s.businesses.id, session.businessId));
  const { date } = await ctx.searchParams;
  const dateISO =
    date ??
    new Intl.DateTimeFormat("en-CA", { timeZone: biz.timezone }).format(new Date()); // YYYY-MM-DD today, business-local

  const dayStart = new Date(localTimeToUtc(dateISO, "00:00", biz.timezone));
  const dayEnd = new Date(dayStart.getTime() + 24 * 3600_000);

  const rows = await db
    .select({
      id: s.bookings.id,
      startAt: s.bookings.startAt,
      endAt: s.bookings.endAt,
      status: s.bookings.status,
      priceKzt: s.bookings.priceKzt,
      staffName: s.staff.name,
      staffId: s.staff.id,
      serviceName: s.services.name,
      clientName: s.clients.name,
      clientPhone: s.clients.phone,
    })
    .from(s.bookings)
    .innerJoin(s.staff, eq(s.bookings.staffId, s.staff.id))

