new='''  const wallMs = Date.UTC(y, m - 1, d, hh, mm);
  // Offsets in effect shortly before and after this wall time bracket any transition.
  const before = tzOffsetMinutes(timeZone, wallMs - 24 * 3600_000);
  const after = tzOffsetMinutes(timeZone, wallMs + 24 * 3600_000);
  const candidates = [before, after]
    .map((o) => wallMs - o * 60000)
    .filter((t, i, arr) => arr.indexOf(t) === i)
